import subprocess
import sys
from pathlib import Path
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("warehouse-inventory")

SCRIPT = Path("/opt/warehouse/scripts/reconcile_counts.py")


@mcp.tool()
def run_cycle_count_reconciliation(zone: str, count_file: str, timeout_s: int = 300) -> dict:
    p = Path(count_file)
    if not p.is_file():
        return {"ok": False, "error": f"count file not found: {count_file}"}
    if not zone.isalnum():
        return {"ok": False, "error": "invalid zone code"}
    cmd = [
        sys.executable,
        "-I",
        str(SCRIPT),
        "--zone",
        zone,
        "--counts",
        str(p),
    ]
    try:
        r = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=timeout_s,
        )
    except subprocess.TimeoutExpired:
        return {"ok": False, "error": f"timed out after {timeout_s}s"}
    out = r.stdout.strip().splitlines()
    err = r.stderr.strip().splitlines()
    return {
        "ok": r.returncode == 0,
        "code": r.returncode,
        "stdout": out[-50:],
        "stderr": err[-20:],
    }

import sqlite3
import logging

log = logging.getLogger(__name__)

DB = "warehouse.db"


def delete_discontinued_sku_records(skus, force=False):
    if not skus:
        return {"deleted": {}, "skipped": []}
    c = sqlite3.connect(DB)
    c.row_factory = sqlite3.Row
    out = {"deleted": {}, "skipped": []}
    try:
        for s in skus:
            row = c.execute(
                "SELECT status FROM skus WHERE sku = ?", (s,)
            ).fetchone()
            if row is None:
                out["skipped"].append({"sku": s, "reason": "unknown"})
                continue
            if row["status"] != "discontinued":
                out["skipped"].append({"sku": s, "reason": "not discontinued"})
                continue
            n = c.execute(
                "SELECT COALESCE(SUM(quantity), 0) FROM bin_stock WHERE sku = ?",
                (s,),
            ).fetchone()[0]
            if n > 0 and not force:
                out["skipped"].append({"sku": s, "reason": f"{n} units on hand"})
                continue
            cnt = {}
            for t in ("bin_stock", "lots", "reorder_rules", "skus"):
                cur = c.execute(f"DELETE FROM {t} WHERE sku = ?", (s,))
                cnt[t] = cur.rowcount
            out["deleted"][s] = cnt
            log.info("deleted sku %s: %s", s, cnt)
        c.commit()
    except sqlite3.Error:
        c.rollback()
        raise
    finally:
        c.close()
    return out
